files.enclosure/gen.mjs:
// node enclosure/gen.mjs — writes the enclosure's CAD trees from one set of numbers.
// Printed parts go in enclosure/*.json (the lab builds each). Reference solids that are not
// printed (the air behind the driver, the driver's bounding cylinder) go in enclosure/ref/.
// Every number that matters is here; the trees carry them as params so the engine can be asked.
// Layout (lid seen from above, x right, y up, origin at the lid's centre):
//   nest (card pocket) on the left, grille over the speaker on the right, two arcade buttons
//   bottom-left, the volume pot bottom-right. The speaker pod hangs under the grille, away from
//   the nest, so no metal (the driver's magnet) sits over the PN532 antenna.
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
export const P = {
  // box
  L: 190, W: 130, H: 75, wall: 2.5, floor: 2.5, post: 8, pilot: 2.5, pilotDepth: 15,
  // lid
  lidT: 4, nestFloor: 2,            // nestFloor is the plastic between card and antenna: PROVISIONAL until the hour of polls
  card: [88, 63], nestClear: 1.0,   // per side; TAPE-ENC-NEST wants 0.5..1.5
  nestC: [-42, 12], screw: 3.4,
  button: 30, buttons: [[-65, -43], [-20, -43]], pot: 7, potC: [75, -48],
  // speaker
  spkC: [44, 9], grilleR: 33, hole: 3.5, pitch: 4.8,
  podL: 78, podW: 84, podH: 55, podWall: 2.5, podFloor: 2.5,
  baffleT: 3, collar: 6, driverHole: 36,
  // the driver, bounded: 40 mm frame, a generous Ø41 × 25 mm cylinder from the baffle top down
  drvR: 20.5, drvDepth: 25,
  // USB-C to the DevKit through the left wall
  usb: [13, 7], usbZ: 15,
};

const tree = (note, params, features) => ({ $schema: 'com.minomobi.cad.tree#v1', units: 'mm', _: note, params, features });
const rect = (name, c, w, h) => ({ name, rect: { c, w, h } });
const circ = (name, c, r) => ({ name, circle: { c, r } });

// Hex grid of grille holes whose whole hole lies inside grilleR of the speaker centre.
export function grilleHoles(p = P) {
  const out = [], r = p.hole / 2, dy = p.pitch * Math.sqrt(3) / 2, n = Math.ceil(p.grilleR / dy) + 1;
  for (let j = -n; j <= n; j++) for (let i = -n; i <= n; i++) {
    const x = (i + (j & 1) / 2) * p.pitch, y = j * dy;
    if (Math.hypot(x, y) + r <= p.grilleR + 1e-9) out.push([+(p.spkC[0] + x).toFixed(4), +(p.spkC[1] + y).toFixed(4)]);
  }
  return out;
}
const postCentres = (p) => { const x = p.L / 2 - p.wall - p.post / 2, y = p.W / 2 - p.wall - p.post / 2; return [[x, y], [-x, y], [-x, -y], [x, -y]]; };

export function parts(p = P) {
  const nestW = p.card[0] + 2 * p.nestClear, nestH = p.card[1] + 2 * p.nestClear;
  const holes = grilleHoles(p);
  const lid = tree('Lid: the card nest (a pocket, nestFloor of plastic over the antenna), the grille over the speaker, two 30 mm arcade buttons, the volume pot, four screw holes into the body posts.',
    { L: p.L, W: p.W, lidT: p.lidT, nestFloor: p.nestFloor, nestW, nestH, hole: p.hole, button: p.button, pot: p.pot, screw: p.screw },
    [
      { op: 'sketch', id: 'top', loops: [
        rect('rim', [0, 0], 'L', 'W'),
        ...holes.map((c, k) => circ(`grille${k}`, c, 'hole/2')),
        ...p.buttons.map((c, k) => circ(`button${k}`, c, 'button/2')),
        circ('pot', p.potC, 'pot/2'),
        ...postCentres(p).map((c, k) => circ(`screw${k}`, c, 'screw/2')),
      ] },
      { op: 'extrude', id: 'lid', profile: 'top', depth: 'lidT' },
      { op: 'sketch', id: 'nestS', plane: { base: 'XY', offset: 'nestFloor' }, loops: [rect('nest', p.nestC, 'nestW', 'nestH')] },
      { op: 'extrude', id: 'nest', profile: 'nestS', mode: 'cut', from: 0, to: 'lidT' },
    ]);

  const pc = postCentres(p), hx = p.L / 2 - p.wall, hy = p.W / 2 - p.wall, s = p.post;
  // cavity outline: the inner rectangle with a square notch left standing in each corner (the posts)
  const cav = [
    [hx - s, -hy], [hx - s, -hy + s], [hx, -hy + s], [hx, hy - s], [hx - s, hy - s], [hx - s, hy],
    [-hx + s, hy], [-hx + s, hy - s], [-hx, hy - s], [-hx, -hy + s], [-hx + s, -hy + s], [-hx + s, -hy],
  ];
  const body = tree('Body: an open tray, corner posts left standing by the cavity outline, pilot holes for the lid screws, a USB-C slot in the left wall for the DevKit (wave 1 runs on USB).',
    { L: p.L, W: p.W, H: p.H, floor: p.floor, pilot: p.pilot, pilotDepth: p.pilotDepth, usbW: p.usb[0], usbH: p.usb[1], usbZ: p.usbZ, wall: p.wall },
    [
      { op: 'sketch', id: 'outer', loops: [rect('outside', [0, 0], 'L', 'W')] },
      { op: 'extrude', id: 'body', profile: 'outer', depth: 'H' },
      { op: 'sketch', id: 'cavS', plane: { base: 'XY', offset: 'floor' }, loops: [{ name: 'cavity', polygon: cav }] },
      { op: 'extrude', id: 'cavity', profile: 'cavS', mode: 'cut', from: 0, to: 'H' },
      { op: 'sketch', id: 'pilotS', plane: { base: 'XY', offset: 'H - pilotDepth' }, loops: pc.map((c, k) => circ(`pilot${k}`, c, 'pilot/2')) },
      { op: 'extrude', id: 'pilots', profile: 'pilotS', mode: 'cut', from: 0, to: 'pilotDepth' },
      { op: 'sketch', id: 'usbS', plane: { base: 'YZ', offset: -p.L / 2 - 1 }, loops: [rect('usb', [0, 'usbZ'], 'usbW', 'usbH')] },
      { op: 'extrude', id: 'usbSlot', profile: 'usbS', mode: 'cut', from: 0, to: 'wall + 2' },
    ]);

  // Truck could not cut the collar's pocket into a plate that already had the driver hole
  // ("shell is not oriented and closed"), so baffle and collar are two parts, both pure even-odd extrudes.
  const baffle = tree('Baffle: a plate that closes the top of the pod. The driver sits on it face-up over the hole, sealed with a bead of silicone round its frame.',
    { podL: p.podL, podW: p.podW, baffleT: p.baffleT, driverHole: p.driverHole },
    [
      { op: 'sketch', id: 'base', loops: [rect('outline', p.spkC, 'podL', 'podW'), circ('driver', p.spkC, 'driverHole/2')] },
      { op: 'extrude', id: 'baffle', profile: 'base', depth: 'baffleT' },
    ]);
  const collar = tree('Collar: a rectangular ring glued between baffle and lid. Its inside is the front chamber, open to the room only through the grille; it keeps the cone from talking into the box.',
    { podL: p.podL, podW: p.podW, wall: p.podWall, collar: p.collar },
    [
      { op: 'sketch', id: 'ring', loops: [rect('outline', p.spkC, 'podL', 'podW'), rect('front', p.spkC, 'podL - 2*wall', 'podW - 2*wall')] },
      { op: 'extrude', id: 'collar', profile: 'ring', depth: 'collar' },
    ]);

  const pod = tree('Pod: the sealed back chamber. An open cup glued (silicone) to the underside of the baffle; nothing else opens into it.',
    { podL: p.podL, podW: p.podW, podH: p.podH, wall: p.podWall, floor: p.podFloor },
    [
      { op: 'sketch', id: 'base', loops: [rect('outline', p.spkC, 'podL', 'podW')] },
      { op: 'extrude', id: 'pod', profile: 'base', depth: 'podH' },
      { op: 'sketch', id: 'airS', plane: { base: 'XY', offset: 'floor' }, loops: [rect('air', p.spkC, 'podL - 2*wall', 'podW - 2*wall')] },
      { op: 'extrude', id: 'air', profile: 'airS', mode: 'cut', from: 0, to: 'podH' },
    ]);

  // Reference solids, not printed. backAir is the pod's cavity as a solid; driverBound is what the driver may occupy.
  const backAir = tree('Reference, not printed: the air inside the pod, as a solid.',
    { a: p.podL - 2 * p.podWall, b: p.podW - 2 * p.podWall, h: p.podH - p.podFloor },
    [{ op: 'sketch', id: 's', loops: [rect('air', p.spkC, 'a', 'b')] }, { op: 'extrude', id: 'air', profile: 's', depth: 'h' }]);
  const driverBound = tree('Reference, not printed: a cylinder the 40 mm driver fits inside (Ø41 × 25 from the baffle top down). Its volume is subtracted from the back air whole, which over-counts the intrusion: the safe side.',
    { r: p.drvR, d: p.drvDepth },
    [{ op: 'sketch', id: 's', loops: [circ('driver', p.spkC, 'r')] }, { op: 'extrude', id: 'driver', profile: 's', depth: 'd' }]);

  return { printed: { lid, body, baffle, collar, pod }, ref: { 'back-air': backAir, 'driver-bound': driverBound }, derived: { nestW, nestH, holes } };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { printed, ref, derived } = parts();
  mkdirSync(join(here, 'ref'), { recursive: true });
  for (const [k, t] of Object.entries(printed)) writeFileSync(join(here, `${k}.json`), JSON.stringify(t, null, 1) + '\n');
  for (const [k, t] of Object.entries(ref)) writeFileSync(join(here, 'ref', `${k}.json`), JSON.stringify(t, null, 1) + '\n');
  // The stack, for check.mjs: body on the floor, lid on the walls, collar/baffle/pod hanging under the lid.
  const p = P, zl = p.H, zc = zl - p.collar, zb = zc - p.baffleT, zp = zb - p.podH;
  const asm = { $schema: 'com.minomobi.cad.tree#v1', units: 'mm', _: 'Reference: the printed parts stacked as built. Glued joints are declared contact.',
    parts: printed,
    components: [
      { id: 'body', part: 'body', at: [0, 0, 0] }, { id: 'lid', part: 'lid', at: [0, 0, zl] },
      { id: 'collar', part: 'collar', at: [0, 0, zc] }, { id: 'baffle', part: 'baffle', at: [0, 0, zb] }, { id: 'pod', part: 'pod', at: [0, 0, zp] },
    ],
    fits: [['lid', 'body'], ['collar', 'lid'], ['baffle', 'collar'], ['pod', 'baffle']].map(([a, b]) => ({ a, b, contact: true })) };
  writeFileSync(join(here, 'ref', 'stack.json'), JSON.stringify(asm, null, 1) + '\n');
  console.log(`wrote ${Object.keys(printed).length} parts, ${Object.keys(ref).length} reference solids; ${derived.holes.length} grille holes`);
}

files.enclosure/measure.mjs:
// node enclosure/measure.mjs [--write] — builds every enclosure tree in the exact kernel (engines/cad,
// Truck) and computes TAPE-ENC's numbers from the built models, not from gen.mjs's params:
//   E     every printed part builds, is watertight, fits a 200 mm cube; one has two dims ≥ 89 and ≥ 64
//   NEST  the nest pocket's walls, read off the lid's named planar faces, clear an 88 × 63 card 0.5..1.5 mm per side
//   SEAL  back air = pod volume (bbox − solid, exact for a rectangular cup), cross-checked against the
//         reference air solid; minus the driver's bounding cylinder; must be ≥ 200 cm³
//   GRILLE every grille hole, read off the lid's named cylinder faces, is under 4 mm; summed open area
//         ≥ 1257 mm²; every hole lies inside the collar's front chamber (else it would vent the box, not the cone)
// --write saves enclosure/ref/measures.json (not in enclosure/: the lab builds every enclosure/*.json as a part). Exits 1 if anything fails.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, readdirSync, mkdtempSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const cad = join(here, '..', 'engines', 'cad');

export function build(file) {
  const dir = mkdtempSync(join(tmpdir(), 'enc-')), out = join(dir, 'r.json');
  try {
    try { execFileSync(process.execPath, ['agent/build.mjs', file, '--json', out], { cwd: cad, stdio: 'pipe' }); }
    catch (e) { try { return JSON.parse(readFileSync(out, 'utf8')); } catch { return { ok: false, error: String(e.stderr || e.message).slice(0, 400) }; } }
    return JSON.parse(readFileSync(out, 'utf8'));
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
const named = (r, re) => r.faces.filter((f) => f.names.some((n) => re.test(n)));
const dims = (r) => { const [a, b] = r.invariants.bbox; return [0, 1, 2].map((i) => b[i] - a[i]); };

export function measure() {
  const files = readdirSync(here).filter((f) => f.endsWith('.json')).sort();
  const res = {}, fail = [];
  for (const f of files) res[f.replace(/\.json$/, '')] = build(join(here, f));
  const out = { parts: {}, E: {}, NEST: {}, SEAL: {}, GRILLE: {} };

  // E
  let nestHolder = null;
  for (const [k, r] of Object.entries(res)) {
    const ok = !!(r.ok && r.invariants && r.invariants.watertight);
    const d = ok ? dims(r) : null, s = d ? [...d].sort((a, b) => b - a) : null;
    out.parts[k] = { ok, watertight: ok, dims: d && d.map((x) => +x.toFixed(4)), volume: ok ? +r.invariants.volume.toFixed(3) : null };
    if (!ok) fail.push(`E: ${k} did not build watertight (${JSON.stringify(r.error || 'not watertight').slice(0, 200)})`);
    else if (Math.max(...d) > 200) fail.push(`E: ${k} is ${Math.max(...d)} mm, over the 200 mm cube`);
    if (s && s[0] >= 89 && s[1] >= 64) nestHolder = nestHolder || k;
  }
  out.E = { printed: files.length, cardSized: nestHolder };
  if (!nestHolder) fail.push('E: no part is 89 × 64 or larger');
  const lid = res.lid, baffle = res.baffle, collar = res.collar, pod = res.pod;
  if (![lid, baffle, collar, pod].every((r) => r && r.ok)) { out.fail = fail.concat('lid, baffle, collar and pod must all build'); return out; }

  // NEST: the pocket's four side walls are planes named nest.nest[k]; their positions bound the pocket.
  const walls = named(lid, /^nest\.nest\[\d\]$/).filter((f) => f.geom && f.geom.kind === 'plane');
  const xs = walls.filter((f) => Math.abs(f.normal[0]) > 0.99).map((f) => f.centroid[0]);
  const ys = walls.filter((f) => Math.abs(f.normal[1]) > 0.99).map((f) => f.centroid[1]);
  const floorZ = named(lid, /^nest\./).filter((f) => Math.abs(f.normal[2]) > 0.99).map((f) => f.centroid[2]);
  const pw = Math.max(...xs) - Math.min(...xs), ph = Math.max(...ys) - Math.min(...ys);
  const cx = [(pw - 88) / 2, (ph - 63) / 2];
  out.NEST = { pocket: [+pw.toFixed(4), +ph.toFixed(4)], clearancePerSide: cx.map((x) => +x.toFixed(4)), floorAboveBottom: floorZ.length ? +Math.min(...floorZ).toFixed(4) : null, walls: walls.length };
  if (walls.length < 4 || xs.length < 2 || ys.length < 2) fail.push(`NEST: found ${walls.length} pocket walls, need 4`);
  for (const c of cx) if (!(c >= 0.5 && c <= 1.5)) fail.push(`NEST: clearance ${c.toFixed(3)} mm per side is outside 0.5..1.5`);

  // SEAL
  const pd = dims(pod), cavity = pd[0] * pd[1] * pd[2] - pod.invariants.volume;
  const air = res['ref/back-air'] || build(join(here, 'ref', 'back-air.json'));
  const drv = build(join(here, 'ref', 'driver-bound.json'));
  const net = cavity - drv.invariants.volume;
  out.SEAL = { podCavity_cm3: +(cavity / 1000).toFixed(3), airSolid_cm3: +(air.invariants.volume / 1000).toFixed(3), driverBound_cm3: +(drv.invariants.volume / 1000).toFixed(3), net_cm3: +(net / 1000).toFixed(3) };
  if (Math.abs(cavity - air.invariants.volume) > 1e-3 * cavity) fail.push(`SEAL: pod cavity ${cavity.toFixed(1)} and air solid ${air.invariants.volume.toFixed(1)} disagree`);
  if (!(drv.ok && drv.invariants.volume > 0 && Math.abs(cavity - drv.invariants.volume - net) < 1)) fail.push('SEAL: the driver bound was not subtracted');
  if (!(net >= 200000)) fail.push(`SEAL: net back air ${(net / 1000).toFixed(1)} cm³ < 200`);

  // GRILLE: one hole per grilleN loop, from its cylinder faces.
  const holes = new Map();
  for (const f of named(lid, /^lid\.grille\d+\[/)) {
    if (!f.geom || f.geom.kind !== 'cylinder') continue;
    const k = f.names.find((n) => /^lid\.grille\d+\[/.test(n)).match(/grille(\d+)/)[1];
    const h = holes.get(k) || { r: 0, c: f.geom.center };
    h.r = Math.max(h.r, f.geom.radius); holes.set(k, h);
  }
  const front = named(collar, /^collar\.front\[\d\]$/).filter((f) => f.geom && f.geom.kind === 'plane');
  const fx = front.filter((f) => Math.abs(f.normal[0]) > 0.99).map((f) => f.centroid[0]);
  const fy = front.filter((f) => Math.abs(f.normal[1]) > 0.99).map((f) => f.centroid[1]);
  const [x0, x1, y0, y1] = [Math.min(...fx), Math.max(...fx), Math.min(...fy), Math.max(...fy)];
  let area = 0, maxD = 0, outside = 0;
  for (const { r, c } of holes.values()) {
    area += Math.PI * r * r; maxD = Math.max(maxD, 2 * r);
    if (!(c[0] - r > x0 && c[0] + r < x1 && c[1] - r > y0 && c[1] + r < y1)) outside++;
  }
  out.GRILLE = { holes: holes.size, maxDiameter: +maxD.toFixed(4), openArea_mm2: +area.toFixed(2), outsideFrontChamber: outside, frontChamber: [x0, x1, y0, y1].map((v) => +v.toFixed(3)) };
  if (!(holes.size > 0 && maxD < 4)) fail.push(`GRILLE: largest hole ${maxD.toFixed(3)} mm (need < 4)`);
  if (!(area >= 1257)) fail.push(`GRILLE: open area ${area.toFixed(1)} mm² < 1257`);
  if (outside) fail.push(`GRILLE: ${outside} holes fall outside the front chamber`);
  if (fx.length < 2 || fy.length < 2) fail.push('GRILLE: could not find the front chamber walls');
  out.fail = fail;
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const m = measure();
  console.log(JSON.stringify(m, null, 1));
  if (process.argv.includes('--write')) writeFileSync(join(here, 'ref', 'measures.json'), JSON.stringify(m, null, 1) + '\n');
  process.exit(m.fail.length ? 1 : 0);
}

files.enclosure/test-geom.mjs:
// node enclosure/test-geom.mjs — regenerate the trees from gen.mjs, then measure them. Exit 1 on any failure.
// Exists for mutants: test.mjs's T-E-GEN catches *any* change to gen.mjs as a stale tree, which says
// nothing about whether the measurements would catch bad geometry. This one asks only the latter.
// node shelf/mutants.mjs . shelf/tape1-enc-mutants.json enclosure/test-geom.mjs
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const here = dirname(fileURLToPath(import.meta.url));
execFileSync(process.execPath, [join(here, 'gen.mjs')], { stdio: 'ignore' });
const { measure } = await import('./measure.mjs');
const m = measure();
for (const f of m.fail) console.log('FAIL', f);
console.log(m.fail.length ? `${m.fail.length} enclosure failures` : 'enclosure ok');
process.exit(m.fail.length ? 1 : 0);

files.fake-sd.mjs:
// A stand-in for the lab's SD card and the box's flash. cutAt = n makes the n-th changing
// call (0-based) fail as power does: a write/append leaves the first half of its text, a
// rename/remove does nothing, and the call throws.
export class PowerCut extends Error {}

export function makeSD(files = {}, dirs = []) {
  const f = new Map(Object.entries(files));
  const d = new Set(dirs);
  for (const p of f.keys()) addParents(p);
  function addParents(p) { const parts = p.split('/'); for (let i = 2; i < parts.length; i++) d.add(parts.slice(0, i).join('/')); }
  const sd = {
    files: f, dirs: d, steps: 0, cutAt: -1, writes: [],
    step(kind, path, half) {
      const n = sd.steps++;
      sd.writes.push([kind, path]);
      if (n === sd.cutAt) { if (half) half(); throw new PowerCut(`cut at step ${n} (${kind} ${path})`); }
    },
    list(dir) {
      const pre = dir.replace(/\/$/, '') + '/'; const out = new Set();
      for (const p of [...f.keys(), ...d]) if (p.startsWith(pre)) { const rest = p.slice(pre.length); if (rest) out.add(rest.split('/')[0]); }
      return [...out].reverse(); // "no particular order"
    },
    isDir(p) { return d.has(p); },
    read(p) { return f.has(p) ? f.get(p) : null; },
    write(p, text) { sd.step('write', p, () => { f.set(p, text.slice(0, text.length >> 1)); addParents(p); }); f.set(p, text); addParents(p); },
    append(p, text) { const old = f.get(p) ?? ''; sd.step('append', p, () => { f.set(p, old + text.slice(0, text.length >> 1)); addParents(p); }); f.set(p, old + text); addParents(p); },
    rename(a, b) { sd.step('rename', a); if (f.has(a)) { f.set(b, f.get(a)); f.delete(a); } },
    remove(p) { sd.step('remove', p); f.delete(p); },
    snapshot() { return JSON.stringify([...f.entries()].sort()); },
  };
  return sd;
}

export function makeFlash(init = null) {
  let v = init === null ? null : JSON.parse(JSON.stringify(init));
  return { get: () => (v === null ? null : JSON.parse(JSON.stringify(v))), set: (x) => { v = JSON.parse(JSON.stringify(x)); }, peek: () => v };
}

// A household SD card: books are folders of tracks.
export function library(books, extra = {}) {
  const files = { ...extra };
  for (const [name, n] of Object.entries(books)) for (let i = 1; i <= n; i++) files[`/tape/audio/${name}/${String(i).padStart(2, '0')}.m4a`] = 'audio';
  return files;
}

