// harness — one model, two runs: record it under runRealtime with a fake clock, replay
// its log under run(), and check every decision matches. No dependencies beyond des.
// Decisions SPEC.md leaves open are marked DECISION and listed in README.md.
import { Sim } from './tools/des/des.mjs';

// A clock that only moves when slept. sleep(ms) delivers at most one due injection:
// it advances the clock to that injection's time, injects, and returns, so the run
// loop sees the injected entry before anything later happens.
function fakeClock(sim, pending, scale, log) {
  const clock = {
    t: 0,
    now() { return clock.t; },
    sleep(ms) {
      const end = clock.t + ms;
      // DECISION: an injection is due when its clock time is strictly before the end of
      // the sleep. One at exactly the next event's time waits for the next sleep, so it
      // is delivered after every entry at that sim time, the same rule replay uses.
      if (pending.length && pending[0].at * scale < end) {
        const inj = pending.shift();
        clock.t = Math.max(clock.t, inj.at * scale);
        deliver(sim, inj.name, inj.value, log, inj.at);
      } else clock.t = end;
      return Promise.resolve();
    },
  };
  return clock;
}

// Inject and log the injection at the sim time it is actually delivered (from inside
// the scheduled entry), so the log's order is the order the model saw.
// DECISION (Morphyx, turn 2): the entry is scheduled at sim time `at` exactly, not at
// clock ÷ scale, which drifts an ulp (3 × 0.37 ÷ 0.37 = 2.9999999999999996). Same wake as
// des's _external; never earlier than now.
function deliver(sim, name, value, log, at) {
  const ext = sim._external;
  sim._external = function (fn) {
    sim._external = ext;
    sim.schedule(Math.max(0, at - sim.now), () => { log.push({ t: sim.now, kind: 'inject', data: { name, value: copy(value) } }); fn(); });
    if (sim._wake) { const w = sim._wake; sim._wake = null; w(); }
  };
  try { sim.inject(name, value); } finally { sim._external = ext; }
}

// DECISION: decision data is copied when written, so a model that later mutates the object
// it logged can't rewrite history. fi-5f90c6 fixed (Morphyx, tape turn 1): the copy goes
// through encode/decode, which keep NaN, ±Infinity, -0 and absence. JSON turned NaN and
// ±Infinity into null, so a NaN reading and a missing one looked the same.
function copy(x) { return x === undefined ? null : decode(encode(x)); }

// Every value is written as a tagged array, so nothing a caller writes can be read as the
// encoding: a caller's string is always inside ['s', ...], a caller's object inside ['o', ...].
//   ['z'] null   ['s', str]   ['b', bool]   ['n', finite number]
//   ['x', 'NaN' | 'Infinity' | '-Infinity' | '-0']
//   ['a', [...]] array; an undefined element or a hole is ['u']
//   ['o', [[key, value], ...]] object; a key whose value is undefined is left out (absent)
//   ['u'] undefined at the top level or in an array slot
function tag(v) {
  if (v === null) return ['z'];
  if (v === undefined) return ['u'];
  switch (typeof v) {
    case 'string': return ['s', v];
    case 'boolean': return ['b', v];
    case 'number':
      if (Number.isNaN(v)) return ['x', 'NaN'];
      if (v === Infinity) return ['x', 'Infinity'];
      if (v === -Infinity) return ['x', '-Infinity'];
      if (Object.is(v, -0)) return ['x', '-0'];
      return ['n', v];
    case 'object':
      if (Array.isArray(v)) return ['a', Array.from(v, tag)];
      if (typeof v.toJSON === 'function') return tag(v.toJSON());
      return ['o', Object.keys(v).filter((k) => v[k] !== undefined).map((k) => [k, tag(v[k])])];
    default: throw new TypeError(`encode: cannot encode a ${typeof v}`);
  }
}
const SPECIAL = { NaN: NaN, Infinity: Infinity, '-Infinity': -Infinity, '-0': -0 };
function put(o, k, v) { Object.defineProperty(o, k, { value: v, enumerable: true, writable: true, configurable: true }); }
function untag(t) {
  if (!Array.isArray(t)) throw new TypeError('decode: not an encoded value');
  const [k, p] = t;
  switch (k) {
    case 'z': return null;
    case 'u': return undefined;
    case 's': case 'b': case 'n': return p;
    case 'x': if (Object.hasOwn(SPECIAL, p)) return SPECIAL[p]; break;
    case 'a': return p.map(untag);
    case 'o': { const o = {}; for (const [key, val] of p) { const x = untag(val); if (x !== undefined) put(o, key, x); } return o; }
  }
  throw new TypeError(`decode: unknown tag ${JSON.stringify(k)}`);
}
export function encode(value) { return JSON.stringify(tag(value)); }
export function decode(text) { return untag(JSON.parse(text)); }

function attach(sim, log) {
  sim.decide = (kind, data) => {
    if (typeof kind !== 'string' || !kind) throw new TypeError('decide needs a kind (string)');
    log.push({ t: sim.now, kind, data: copy(data) });
  };
}

export async function record(model, { seed, until, scale = 1, injections = [] } = {}) {
  if (typeof model !== 'function') throw new TypeError('record needs a model function');
  if (!(scale > 0)) throw new RangeError('scale must be > 0');
  for (const j of injections) if (!(j && j.at >= 0 && typeof j.name === 'string')) throw new RangeError(`bad injection ${JSON.stringify(j)}`);
  const log = [];
  // Stable sort: injections at the same time keep the order given.
  const pending = injections.map((j, i) => ({ ...j, i })).sort((a, b) => a.at - b.at || a.i - b.i);
  const sim = new Sim({ seed, clock: null });
  sim._clock = fakeClock(sim, pending, scale, log);
  attach(sim, log);
  await model(sim);
  await sim.runRealtime({ until, scale });
  return log;
}

export async function replay(model, log, { seed, until } = {}) {
  if (typeof model !== 'function') throw new TypeError('replay needs a model function');
  if (!Array.isArray(log)) throw new TypeError('replay needs a log array');
  const got = [];
  const sim = new Sim({ seed });
  attach(sim, got);
  await model(sim);
  for (const e of log) {
    if (e.kind !== 'inject') continue;
    // Recorded rule: an injection at t is delivered after every entry at times <= t
    // that existed when the clock passed t. run({until: t}) processes exactly those
    // (plus same-time entries they spawn, which in record also ran before the sleep).
    sim.run({ until: Math.max(e.t, sim.now) });
    // run() leaves now at until, so the injection lands at e.t, as in record.
    sim.inject(e.data.name, e.data.value);
  }
  if (until !== undefined) { if (until >= sim.now) sim.run({ until }); }
  else sim.run();
  const want = log.filter((e) => e.kind !== 'inject');
  const mismatches = [];
  const n = Math.max(want.length, got.length);
  for (let i = 0; i < n; i++) {
    const a = want[i], b = got[i];
    if (!same(a, b)) mismatches.push({ index: i, expected: a ?? null, got: b ?? null });
  }
  return { ok: mismatches.length === 0, mismatches };
}

// Canonical form: keys sorted, then the tagged encoding, so NaN, null and absent all differ.
function sortKeys(x) {
  if (Array.isArray(x)) return x.map(sortKeys);
  if (x && typeof x === 'object') { const o = {}; for (const k of Object.keys(x).sort()) if (x[k] !== undefined) put(o, k, sortKeys(x[k])); return o; }
  return x;
}
function canon(x) { return encode(sortKeys(x)); }
function same(a, b) {
  if (!a || !b) return false;
  return Object.is(a.t, b.t) && a.kind === b.kind && canon(a.data) === canon(b.data);
}

files.tape1.mjs:
// tape1 — the box without the radio (wave 1). STATE-TABLE.md is the table this follows.
// The card watcher's gone-timer lives on a des clock; everything that touches the SD card
// happens in the async poll/trackEnded/boot calls, never inside a des callback.
import { Sim } from './tools/des/des.mjs';
import { decodeCard, CARD_EXTERNAL_TYPE } from './tape-lib/tag.js';

// DECISION (provisional, CHOICE.md): a card is gone 1.0 s after its last good read. W2 allows
// 1.25; at 20 Hz with iid 25% misses, 20 misses in a row is ~1e-12 a poll. Bursts are not iid,
// and the hour of raw polls through the lid plate decides this number, not this comment.
export const GONE_AFTER = 1.0;

export const AUDIO = '/tape/audio';
export const CARDS = '/tape/cards.json';
export const CARDS_NEW = '/tape/cards.new';
export const UNKNOWN = '/tape/unknown.txt';
export const LOG = '/tape/log.txt';
const TITLE_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
const AUDIO_EXT = new Set(['mp3', 'm4a', 'aac', 'wav', 'ogg', 'opus', 'flac', 'amr']);

const byCodeUnit = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export function isDecodable(name) {
  if (name.startsWith('.')) return false;
  const dot = name.lastIndexOf('.');
  return dot > 0 && AUDIO_EXT.has(name.slice(dot + 1).toLowerCase());
}

export function cardId(read) {
  for (const r of read.records || []) {
    if (!r || r.recordType !== CARD_EXTERNAL_TYPE) continue;
    try {
      let d = r.data;
      if (d instanceof DataView) d = new Uint8Array(d.buffer, d.byteOffset, d.byteLength);
      else if (d instanceof ArrayBuffer) d = new Uint8Array(d);
      return decodeCard(d).id;
    } catch { /* a corrupt record: try the next */ }
  }
  return 'uid:' + String(read.uid).toLowerCase();
}

// A bindings file parses when it is a JSON object whose non-'_' values are all strings.
export function parseBindings(text) {
  if (typeof text !== 'string') return null;
  let v;
  try { v = JSON.parse(text); } catch { return null; }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  const out = {};
  for (const k of Object.keys(v)) {
    if (k.startsWith('_')) continue;
    if (typeof v[k] !== 'string') return null;
    out[k] = v[k];
  }
  return out;
}

export function serialize(bindings) {
  const o = {};
  for (const k of Object.keys(bindings).sort(byCodeUnit)) o[k] = bindings[k];
  return JSON.stringify(o); // no trailing newline: a torn prefix can never close the object
}

async function scan(sd) {
  const titles = new Map(); const bad = [];
  let names = [];
  try { names = (await sd.list(AUDIO)) || []; } catch { names = []; }
  for (const name of [...names].sort(byCodeUnit)) {
    const path = `${AUDIO}/${name}`;
    if (!(await sd.isDir(path))) continue;
    let tracks = [];
    if (TITLE_RE.test(name)) {
      const inner = (await sd.list(path)) || [];
      for (const f of [...inner].sort(byCodeUnit)) if (isDecodable(f) && !(await sd.isDir(`${path}/${f}`))) tracks.push(f);
    }
    if (tracks.length) titles.set(name, tracks); else bad.push(name);
  }
  return { titles, bad };
}

const line = (t, kind, ...rest) => [t, kind, ...rest].join('\t') + '\n';

export async function boot({ sd, flash, t = 0 }) {
  const events = [];
  const sim = new Sim({ seed: 1 });
  if (t > 0) sim.run({ until: t });
  const prior = flash.get();
  const { titles, bad } = await scan(sd);
  const titleList = [...titles.keys()];

  // Who decides the bindings (K): cards.json, else cards.new, else the mirror.
  let bindings = null, decidedBy = null;
  const fromJson = parseBindings(await sd.read(CARDS));
  if (fromJson) { bindings = fromJson; decidedBy = 'cards.json'; }
  else {
    const fromNew = parseBindings(await sd.read(CARDS_NEW));
    if (fromNew) { bindings = fromNew; decidedBy = 'cards.new'; }
    else if (prior && prior.bindings) { bindings = { ...prior.bindings }; decidedBy = 'mirror'; }
  }
  if (!bindings) bindings = {};

  const sdChange = !!(prior && Array.isArray(prior.titles) && prior.titles.join('/') !== titleList.join('/'));
  const mirror = decidedBy && decidedBy !== 'mirror' ? { ...bindings } : prior && prior.bindings ? { ...prior.bindings } : null;
  flash.set({ v: 1, titles: titleList, bindings: mirror });

  // A cut append leaves half a line: start the boot line on a fresh one so it can't merge.
  const logText = await sd.read(LOG);
  const fresh = logText && !logText.endsWith('\n') ? '\n' : '';
  await sd.append(LOG, fresh + line(t, 'boot', `titles=${titleList.length}`, `cards=${Object.keys(bindings).length}`, `from=${decidedBy || 'none'}`, ...(sdChange ? ['sd-change'] : [])));
  for (const b of bad) await sd.append(LOG, line(t, 'bad-folder', b));
  if (decidedBy === 'mirror') {
    events.push({ t, type: 'restore' });
    await sd.append(LOG, line(t, 'restore', `cards=${Object.keys(bindings).length}`));
  }

  // Housekeeping: leave exactly one bindings file that decides, holding what the box decided.
  if (decidedBy === 'cards.json') {
    if ((await sd.read(CARDS_NEW)) !== null) await sd.remove(CARDS_NEW);
  } else if (decidedBy === 'cards.new') {
    await sd.rename(CARDS_NEW, CARDS);
  } else if (decidedBy === 'mirror') {
    await sd.write(CARDS_NEW, serialize(bindings));
    await sd.rename(CARDS_NEW, CARDS);
  }

  // Card watcher + player state.
  let pad = 'empty';          // 'empty' | 'card' | 'crowd'
  let card = null;            // id of the card on the pad
  let playing = null;         // { title, track } while sound plays
  let timer = null;
  const position = new Map(); // card -> track to resume from, this power session

  const emit = (e) => events.push(e);
  function stop(at) {
    if (playing) { position.set(card, playing.track); emit({ t: at, type: 'pause' }); playing = null; }
  }
  function gone() { timer = null; stop(sim.now); pad = 'empty'; card = null; }
  function arm() { if (timer) sim.cancel(timer); timer = sim.schedule(GONE_AFTER, gone); }

  function play(at, id, title, track) {
    playing = { title, track };
    emit({ t: at, type: 'play', card: id, title, track, file: titles.get(title)[track] });
  }

  async function place(at, id) {
    pad = 'card'; card = id; arm();
    let title = Object.hasOwn(bindings, id) ? bindings[id] : null;
    if (title !== null) {
      if (!titles.has(title)) {
        emit({ t: at, type: 'cue', card: id, reason: 'missing' });
        await sd.append(LOG, line(at, 'missing', id, title));
        return;
      }
      const from = position.get(id) ?? 0;
      play(at, id, title, from < titles.get(title).length ? from : 0);
      return;
    }
    const taken = new Set(Object.values(bindings));
    title = titleList.find((x) => !taken.has(x));
    if (title === undefined) {
      emit({ t: at, type: 'cue', card: id });
      await sd.append(UNKNOWN, id + '\n');
      await sd.append(LOG, line(at, 'cue', id));
      return;
    }
    const next = { ...bindings, [id]: title };
    await sd.write(CARDS_NEW, serialize(next));
    await sd.rename(CARDS_NEW, CARDS);         // the bind is durable here, and not before
    bindings = next;
    const f = flash.get() || {};
    flash.set({ ...f, v: 1, bindings: { ...bindings } });
    emit({ t: at, type: 'bound', card: id, title });
    await sd.append(LOG, line(at, 'bind', id, title));
    position.delete(id);
    play(at, id, title, 0);
  }

  const box = {
    events,
    async poll(at, read) {
      sim.run({ until: Math.max(at, sim.now) });
      if (read == null) return;
      if (read.crowd) {
        if (timer) { sim.cancel(timer); timer = null; }
        stop(at);
        pad = 'crowd'; card = null;
        return;
      }
      const id = cardId(read);
      if (pad === 'card' && card === id) { arm(); return; }
      if (pad === 'card') { stop(at); if (timer) { sim.cancel(timer); timer = null; } }
      await place(at, id);
    },
    async trackEnded(at) {
      sim.run({ until: Math.max(at, sim.now) });
      if (!playing) return;
      const tracks = titles.get(playing.title);
      if (playing.track + 1 < tracks.length) { play(at, card, playing.title, playing.track + 1); return; }
      const title = playing.title;
      playing = null; position.set(card, 0);
      emit({ t: at, type: 'finished', title });
      await sd.append(LOG, line(at, 'finished', title));
    },
    // Read-only views for tests and the README; the lab ignores them.
    get state() { return { pad, card, playing: playing && { ...playing }, bindings: { ...bindings }, titles: titleList.slice(), decidedBy }; },
  };
  return box;
}

files.test.mjs:
// node test.mjs — runs every check, writes evidence.json (stamped by Fresh), exits 0 only if
// all pass. Check ids are linked to requirements in links.json.
import { readFileSync, writeFileSync } from 'node:fs';
import { encode, decode, record, replay } from './harness.mjs';
import { boot, GONE_AFTER, CARDS, CARDS_NEW, LOG, UNKNOWN } from './tape1.mjs';
import { makeSD, makeFlash, library, PowerCut } from './fake-sd.mjs';
import { ndefRecords } from './tape-lib/tag.js';
import { stamp } from './fresh.mjs';
import { Sim } from './tools/des/des.mjs';

const results = [];
async function check(id, fn) {
  try { await fn(); results.push({ check: id, result: 'pass' }); }
  catch (e) { results.push({ check: id, result: 'fail', detail: String(e && e.stack || e) }); console.log(`FAIL ${id}: ${e && e.message}`); }
}
function assert(c, msg) { if (!c) throw new Error(msg); }
function rng(seed) { let s = seed >>> 0 || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }

const tagRead = (uid, id) => ({ uid, records: id ? ndefRecords({ id }) : null });
const ID = ['A000000000000', 'B000000000000', 'C000000000000', 'D000000000000', 'E000000000000'];
const types = (box) => box.events.map((e) => e.type);
const logKinds = (sd) => (sd.read(LOG) || '').split('\n').filter(Boolean).map((l) => l.split('\t')[1]);

// Hold a card on the pad from t0 for dur seconds at 20 Hz; miss is the chance a poll reads nothing.
async function hold(box, read, t0, dur, miss = 0, r = Math.random) {
  let t = t0, last = null;
  for (let i = 0; t0 + i * 0.05 <= t0 + dur + 1e-9; i++) { t = t0 + i * 0.05; if (r() < miss) await box.poll(t, null); else { await box.poll(t, read); last = t; } }
  return { t, last };
}
// The card stays on the pad, read every poll, from t0 (exclusive) until t; then the track ends at t.
async function endAt(box, read, t0, t) { for (let i = 1; t0 + i * 0.05 < t - 1e-9; i++) await box.poll(t0 + i * 0.05, read); await box.poll(t, read); await box.trackEnded(t); }
async function empty(box, t0, dur) { let t = t0; for (let i = 1; i * 0.05 <= dur + 1e-9; i++) { t = t0 + i * 0.05; await box.poll(t, null); } return t; }

// ---------- H: the harness ----------
await check('T-H-ROUNDTRIP', () => {
  const lookalikes = ['["x","NaN"]', '["z"]', '{"o":[]}', 'NaN', 'null', ''];
  const vals = [null, NaN, Infinity, -Infinity, -0, 0, 1.5, 'NaN', true, [], {}, [NaN, null, undefined, -Infinity],
    { a: NaN, b: null, c: undefined, d: { e: Infinity } }, ['x', 'NaN'], ['z'], { s: 'x' }, ['s', 'x'], { __tag: 'NaN' },
    ...lookalikes, lookalikes.map((s) => ({ [s]: s }))];
  const same = (a, b) => {
    if (typeof a === 'number') return Object.is(a, b);
    if (a === null || typeof a !== 'object') return a === b;
    if (Array.isArray(a) !== Array.isArray(b) || !b || typeof b !== 'object') return false;
    const ka = Object.keys(a).filter((k) => a[k] !== undefined || Array.isArray(a)), kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
